        st("Squeeze and mix", "A handful at a time, wring the zucchini very dry in a clean towel and drop it into the large bowl. Mix in the feta, scallions, the remaining dill and mint except 2 tbsp of each, the eggs, flour, and pepper flakes to a thick, spoonable batter.", ["zucchini", "feta", "scallions", "dill", "mint", "eggs", "flour", "pepper-flakes"], 5, "prep"),
        st("Dress the salad", "Toss the tomatoes, cucumber, and red onion with the lemon juice, olive oil, and 1/4 tsp salt.", ["tomatoes", "cucumber", "red-onion", "lemon", "olive-oil", "kosher-salt"], 2, "prep"),
        st("Shallow-fry the fritters", "Heat 2/3 cup neutral oil (about 1/8 inch) in a 12-inch skillet over medium until it shimmers, about 3 minutes. Drop in 6 mounds of batter, 1/3 cup each, and flatten to 3 1/2-inch rounds. Cook until deep golden and set through, turning once, about 8 minutes per batch. Drain on a rack. Add the remaining 2/3 cup oil, heat it about 1 minute, and shallow-fry the rest of the batter (2 batches, 12 fritters).", ["neutral-oil", "zucchini"], 21, "cook"),
        st("Serve", "Plate 3 fritters each, scatter the reserved dill and mint over them, and add a spoonful of garlic yogurt and the salad alongside.", ["zucchini", "dill", "mint", "yogurt", "tomatoes"], 2, "cook"),
